// Generated by `npm run birthday:export` from explicitly selected private
// derivatives. Private originals and source filenames are never included.
const entries = [];
export const BIRTHDAY_PERSONAL_MEDIA = Object.freeze(entries.map((entry) => Object.freeze({
  ...entry,
  videoSources: Object.freeze(Array.from(entry.videoSources || [], (source) => Object.freeze({ ...source })))
})));
